INSERT INTO feature VALUES('build-stage','metaprograms','A package''s build stage','project-manifest','planned','notable',NULL,'A package''s `package.gandr.toml` is written by its own build stage, an operation of its `Package` model the checker runs at the model''s fields and the tree''s modules, memoized by its inputs'' content; today the default stage is spelled as a gandr function whose runs are the bodies the tree commits, and the checker''s fixed rule writes the file.',NULL,'corpus/model/package/build-stage.gandr',NULL,'#2998');
